def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    background = Counter(v for row in out for v in row).most_common(1)[0][0]

    def has_marker(r, c, other):
        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and (nr, nc) != other and out[nr][nc] != background:
                return True
        return False

    rays = set()
    for r in range(h):
        for c in range(w):
            color = out[r][c]
            if color == background:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                nr, nc = r + dr, c + dc
                if nr >= h or not (0 <= nc < w) or out[nr][nc] != color:
                    continue
                a, b = (r, c), (nr, nc)
                if has_marker(*a, b):
                    rays.add((b[0], b[1], dr, dc, color))
                if has_marker(*b, a):
                    rays.add((a[0], a[1], -dr, -dc, color))

    for r, c, dr, dc, color in rays:
        r += dr
        c += dc
        while 0 <= r < h and 0 <= c < w:
            if out[r][c] not in (background, color):
                break
            out[r][c] = color
            r += dr
            c += dc
    return out
